          vyHat += 0.6 * evy;
          if (motorThrust * dirY > 0.22) {
            kT = clamp(kT + 2.2 * evy / (motorThrust * dirY), 13.5, 27.5);
          }
        } else {
          vyHat = v.y;
        }

