          const evz = v.z - vzHat;
          vxHat += 0.7 * evx;
          vzHat += 0.7 * evz;
          wxHat = clamp(wxHat + 30.0 * evx, -18, 18);
          wzHat = clamp(wzHat + 30.0 * evz, -18, 18);
          if (t > 0.25 && t < 1.95) {
