export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01;
  const g = 9.81;

  // State and disturbance estimators
  let initialized = false;
  let kT = 20.0; // Effective max specific thrust (m/s^2)
  let motorThrust = 0;
  let vyHat = 0;
  let vxHat = 0, vzHat = 0;
  let wxHat = 0, wzHat = 0;
  let evzFilt = 0;

  // Inner attitude loop tracking & rotational disturbance observer
  let simIntRoll = 0, simIntPitch = 0;
  let tauFiltRoll = 0, tauFiltPitch = 0;
  let rateHatRoll = 0, rateHatPitch = 0;
  let betaRoll = 0, betaPitch = 0;
  let lastAction = { thrust: 0.5, roll: 0, pitch: 0, yawRate: 0 };

  // Navigation state
  let currentGate = 0;
  let gatePhase = 'approach'; // 'approach' | 'lunge'
  let intZ = 0, intY = 0, intX = 0;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        vyHat = v.y;
        vxHat = v.x;
        vzHat = v.z;
        rateHatRoll = rates.roll;
        rateHatPitch = rates.pitch;
      } else {
        // 1. Update inner attitude loop replica & rotational disturbance observer
        const errRoll = lastAction.roll - att.roll;
        const errPitch = lastAction.pitch - att.pitch;
        simIntRoll = clamp(simIntRoll + errRoll * dt, -0.35, 0.35);
        simIntPitch = clamp(simIntPitch + errPitch * dt, -0.35, 0.35);

        const alphaLag = 1 - Math.exp(-dt / 0.04);
        motorThrust += (lastAction.thrust - motorThrust) * alphaLag;

        const tauCmdRoll = 65 * errRoll - 13 * rates.roll + 22 * simIntRoll;
        const tauCmdPitch = 65 * errPitch - 13 * rates.pitch + 22 * simIntPitch;
        tauFiltRoll += (tauCmdRoll - tauFiltRoll) * alphaLag;
        tauFiltPitch += (tauCmdPitch - tauFiltPitch) * alphaLag;

        rateHatRoll += (tauFiltRoll - 0.4 * rateHatRoll + betaRoll * motorThrust) * dt;
        rateHatPitch += (tauFiltPitch - 0.4 * rateHatPitch + betaPitch * motorThrust) * dt;

        const validAir = (obs.gateIndex < 3 ? p.y > 0.085 : p.y > 0.11) && p.y < 2.88 && motorThrust > 0.20;
        if (validAir) {
          const eRoll = rates.roll - rateHatRoll;
          const ePitch = rates.pitch - rateHatPitch;
          rateHatRoll += 0.65 * eRoll;
          rateHatPitch += 0.65 * ePitch;
          const mScale = Math.max(0.30, motorThrust);
          betaRoll = clamp(betaRoll + (28.0 * eRoll) / mScale, -45, 45);
          betaPitch = clamp(betaPitch + (28.0 * ePitch) / mScale, -45, 45);
        } else {
          rateHatRoll = rates.roll;
          rateHatPitch = rates.pitch;
        }

        // 2. Translational observers
        const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
        const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
        const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
        const bodyX = sp * cr, bodyZ = -sr;
        const dirX = cy * bodyX + sy * bodyZ;
        const dirY = cp * cr;
        const dirZ = -sy * bodyX + cy * bodyZ;

        const cd = 0.42 / clamp(14.5 / kT, 0.6, 0.95);
        const aTot = kT * motorThrust;

        if (validAir) {
          vyHat += (aTot * dirY - g - cd * vyHat) * dt;
          const evy = v.y - vyHat;
          vyHat += 0.6 * evy;
          if (motorThrust * dirY > 0.22) {
            kT = clamp(kT + 2.4 * evy / (motorThrust * dirY), 13.5, 27.5);
          }
        } else {
          vyHat = v.y;
        }

        const nearWall = Math.abs(p.x) > 2.78 || Math.abs(p.z) > 2.78;
        if (validAir && !nearWall) {
          vxHat += (aTot * dirX - cd * vxHat + wxHat) * dt;
          vzHat += (aTot * dirZ - cd * vzHat + wzHat) * dt;
          const evx = v.x - vxHat;
          const evz = v.z - vzHat;
          evzFilt = 0.6 * evzFilt + 0.4 * Math.abs(evz);
          vxHat += 0.72 * evx;
          vzHat += 0.72 * evz;
          wxHat = clamp(wxHat + 32.0 * evx, -20, 20);
          wzHat = clamp(wzHat + 32.0 * evz, -20, 20);
        } else {
          vxHat = v.x;
          vzHat = v.z;
          evzFilt *= 0.8;
        }
      }

      const bRoll = betaRoll * motorThrust;
      const bPitch = betaPitch * motorThrust;

      // 3. Navigation & Trajectory Planning
      let tx = p.x, ty = 1.0, tz = p.z;
      let tvx = 0, tvy = 0, tvz = 0;
      let kpX = 6.5, kdX = 4.4;
      let kpZ = 10.5, kdZ = 5.6;
      let kpY = 8.5, kdY = 5.0;

      if (obs.gateIndex < 3) {
        const gPos = obs.nextGate.centre;
        if (currentGate !== obs.gateIndex) {
          currentGate = obs.gateIndex;
          gatePhase = 'approach';
          intZ = 0;
          intY = 0;
          intX = 0;
        }

        const dxGate = gPos.x - p.x;
        const dyGate = gPos.y - p.y;
        const dzGate = gPos.z - p.z;

        if (Math.abs(dzGate) < 0.14 && dxGate < 0.45 && dxGate > -0.05) {
          intZ = clamp(intZ + dzGate * dt, -0.08, 0.08);
        } else {
          intZ *= 0.9;
        }
        if (Math.abs(dyGate) < 0.20 && dxGate < 0.45 && dxGate > -0.05) {
          intY = clamp(intY + dyGate * dt, -0.10, 0.10);
        } else {
          intY *= 0.9;
        }

        // Predict y and z when crossing x = gPos.x
        const tCross = clamp(dxGate / Math.max(0.55, v.x), 0.02, 0.25);
        const zPred = p.z + v.z * tCross;
        const yPred = p.y + v.y * tCross;

        const zAligned = Math.abs(dzGate) < 0.017 && Math.abs(zPred - gPos.z) < 0.020 && Math.abs(v.z) < 0.16;
        const yAligned = Math.abs(dyGate) < 0.065 && Math.abs(yPred - gPos.y) < 0.085 && Math.abs(v.y) < 0.35;

        if (gatePhase === 'approach') {
          ty = gPos.y;
          tz = gPos.z;
          const standOff = 0.22;
          tx = gPos.x - standOff;

          if (dxGate > 0.32) {
            tvx = clamp((dxGate - standOff) * 1.1, 0, 1.15);
            const distYZ = Math.hypot(dyGate, dzGate);
            if (distYZ > 0.12) {
              const speedYZ = Math.min(1.5, distYZ * 2.2);
              tvy = (dyGate / distYZ) * speedYZ * 0.55;
              tvz = (dzGate / distYZ) * speedYZ * 0.55;
            }
          }

          if (dxGate < 0.34 && dxGate > 0.0 && zAligned && yAligned && evzFilt < 0.045) {
            gatePhase = 'lunge';
          }
        }

        if (gatePhase === 'lunge') {
          ty = gPos.y;
          tz = gPos.z;
          tx = gPos.x + 0.38;
          tvx = 1.05;
          kpZ = 14.0;
          kdZ = 6.4;
          kpY = 10.5;
          kdY = 5.5;

          // Stopping distance check: only abort if we can stop before the gate plane
          const stopDist = Math.max(0.085, v.x * 0.085 + (v.x > 0 ? (v.x * v.x) / 9.5 : 0));
          const zSafeNow = Math.abs(dzGate) < 0.024 && Math.abs(zPred - gPos.z) < 0.026;
          const ySafeNow = Math.abs(dyGate) < 0.10 && Math.abs(yPred - gPos.y) < 0.115;
          if (dxGate > stopDist && (!zSafeNow || !ySafeNow)) {
            gatePhase = 'approach';
            tx = gPos.x - 0.25;
            tvx = -0.25;
            kpX = 11.0;
            kdX = 6.2;
          }
        }

        // If we somehow passed x = gPos.x without crossing (missed gate), recover safely
        if (dxGate <= 0) {
          gatePhase = 'approach';
          if (Math.abs(dzGate) < 0.022 && Math.abs(dyGate) < 0.08) {
            tx = gPos.x - 0.26;
          } else {
            tx = p.x;
            ty = gPos.y;
            tz = gPos.z;
          }
        }
      } else {
        // Gate 3 passed -> fly to landing pad (2.05, 0, 1.65)
        const pad = obs.pad.centre;
        const dxPad = pad.x - p.x;
        const dzPad = pad.z - p.z;
        const distH = Math.hypot(dxPad, dzPad);
        const speedH = Math.hypot(v.x, v.z);

        tx = pad.x;
        tz = pad.z;
        kpX = 9.0; kdX = 5.4;
        kpZ = 9.0; kdZ = 5.4;

        if (distH < 0.25) {
          intX = clamp(intX + dxPad * dt, -0.08, 0.08);
          intZ = clamp(intZ + dzPad * dt, -0.08, 0.08);
        } else {
          intX *= 0.9;
          intZ *= 0.9;
          const speedPad = Math.min(1.2, distH * 1.8);
          tvx = (dxPad / distH) * speedPad * 0.45;
          tvz = (dzPad / distH) * speedPad * 0.45;
        }
        intY = 0;

        // Smooth continuous glide slope toward pad center
        ty = clamp(0.062 + 0.95 * Math.max(0, distH - 0.065), 0.062, 0.65);
        if (distH < 0.11 && p.y > 0.09) {
          tvy = -0.24;
        }

        // Pinned floor hold when on/near pad at floor height
        if (p.y <= 0.092 && distH <= 0.138 && speedH < 0.46) {
          const axHold = clamp(12.0 * dxPad - 5.5 * v.x + 8.0 * intX - 0.7 * wxHat, -1.6, 1.6);
          const azHold = clamp(12.0 * dzPad - 5.5 * v.z + 8.0 * intZ - 0.7 * wzHat, -1.6, 1.6);
          const aHoldY = 5.2;
          const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
          const bX = (cy * axHold - sy * azHold) / aHoldY;
          const bZ = (sy * axHold + cy * azHold) / aHoldY;
          const rDes = clamp(-bZ, -0.13, 0.13);
          const pDes = clamp(bX, -0.13, 0.13);
          const alphaRoll = 115 * (rDes - att.roll) - 19 * rates.roll;
          const alphaPitch = 115 * (pDes - att.pitch) - 19 * rates.pitch;
          const cmdRoll = clamp(att.roll + (alphaRoll + 13 * rates.roll - 22 * simIntRoll - bRoll) / 65, -0.35, 0.35);
          const cmdPitch = clamp(att.pitch + (alphaPitch + 13 * rates.pitch - 22 * simIntPitch - bPitch) / 65, -0.35, 0.35);
          const act = { thrust: clamp(aHoldY / kT, 0.20, 0.35), roll: cmdRoll, pitch: cmdPitch, yawRate: clamp(-0.4 * att.yaw + 0.5 * rates.yaw, -0.5, 0.5) };
          lastAction = act;
          return act;
        }
      }

      // 4. Compute desired world acceleration (including wind cancellation & drag compensation)
      const cd = 0.42 / clamp(14.5 / kT, 0.6, 0.95);
      const ex = tx - p.x, ey = ty - p.y, ez = tz - p.z;
      const evx = tvx - v.x, evy = tvy - v.y, evz = tvz - v.z;

      let axDes = kpX * ex + kdX * evx + 10.0 * intX + cd * v.x - wxHat;
      let azDes = kpZ * ez + kdZ * evz + 12.0 * intZ + cd * v.z - wzHat;
      let ayDes = g + kpY * ey + kdY * evy + 10.0 * intY + cd * v.y;

      // Wall safety barrier
      if (p.x < -2.55 && v.x < 0) axDes = Math.max(axDes, 4.5);
      if (p.x > 2.55 && v.x > 0) axDes = Math.min(axDes, -4.5);
      if (p.z < -2.55 && v.z < 0) azDes = Math.max(azDes, 4.5);
      if (p.z > 2.55 && v.z > 0) azDes = Math.min(azDes, -4.5);
      if (p.y > 2.65 && v.y > 0) ayDes = Math.min(ayDes, g - 3.5);

      ayDes = clamp(ayDes, 2.5, 18.0);
      const maxHorizAcc = 6.8;
      const horizMag = Math.hypot(axDes, azDes);
      if (horizMag > maxHorizAcc) {
        axDes *= maxHorizAcc / horizMag;
        azDes *= maxHorizAcc / horizMag;
      }

      // 5. Exact inverse kinematics from desired thrust vector to (thrust, rollDes, pitchDes)
      const aMag = Math.hypot(axDes, ayDes, azDes);
      const dx = axDes / aMag, dy = ayDes / aMag, dz = azDes / aMag;

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyX = cy * dx - sy * dz;
      const bodyZ = sy * dx + cy * dz;

      // Strict tilt limit near floor when landing so floor contact never exceeds 0.36 rad or 0.18 rad
      let maxTilt = 0.52;
      if (obs.gateIndex === 3) {
        if (p.y < 0.12) maxTilt = 0.15;
        else if (p.y < 0.22) maxTilt = 0.24;
      }
      const rollDes = clamp(-Math.asin(clamp(bodyZ, -0.9, 0.9)), -maxTilt, maxTilt);
      const pitchDes = clamp(Math.atan2(bodyX, dy), -maxTilt, maxTilt);

      // Desired thrust: project target vertical acceleration onto actual attitude direction
      const actualCos = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const thrust = clamp((ayDes / actualCos) / kT, 0.08, 0.98);

      // 6. High-bandwidth inner-loop attitude command with disturbance cancellation
      const alphaRoll = 130 * (rollDes - att.roll) - 20.5 * rates.roll;
      const alphaPitch = 130 * (pitchDes - att.pitch) - 20.5 * rates.pitch;

      const rollCmd = clamp(att.roll + (alphaRoll + 13 * rates.roll - 22 * simIntRoll - bRoll) / 65, -0.6, 0.6);
      const pitchCmd = clamp(att.pitch + (alphaPitch + 13 * rates.pitch - 22 * simIntPitch - bPitch) / 65, -0.6, 0.6);
      const yawRateCmd = clamp(-0.5 * att.yaw + 0.5 * rates.yaw, -0.7, 0.7);

      const action = { thrust, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
      lastAction = action;
      return action;
    },
  };
}

export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01;
  const g = 9.81;

  // State and disturbance estimators
  let initialized = false;
  let kT = 20.0; // Effective max specific thrust (m/s^2)
  let motorThrust = 0;
  let vyHat = 0;
  let vxHat = 0, vzHat = 0;
  let wxHat = 0, wzHat = 0;
